generated_pydough:
counted_captains_by_rank = captains.WHERE(
    age < 50
).PARTITION(
    name="captain_ranks",
    by=(rank)
).CALCULATE(
    rank=rank,
    num_captains=COUNT(captains)
)

tourists_without_visits = cre_Theme_park.CALCULATE(
    count_tourists_no_visits=COUNT(visitor.WHERE(HASNOT(visit) == 1))
)

# Find the claim with the largest total settlement amount and return its effective date
largest_settlement_claim = claim.WHERE(
    HAS(settlement) == 1
).CALCULATE(
    claim_effective_date=effective_date,
    total_settlement_amount=SUM(settlement.settlement_amount)
).TOP_K(1, by=total_settlement_amount.DESC()).CALCULATE(
    claim_effective_date=claim_effective_date
)

# Find dates of assessment notes for students with first name "Fanny"
fanny_assessment_dates = assessment_note.WHERE(
    student.first_name == "Fanny"
).CALCULATE(
    date_of_notes=date_of_notes
)

most_ordered_product = invoice.PARTITION(name="products_invoices", by=product_id).CALCULATE(
    product_id=product_id,
    order_count=COUNT(invoice)
).TOP_K(1, by=order_count.DESC()).CALCULATE(
    product_id=product_id
)

room_names_with_roy_customers = inn_1.reservation.WHERE(
    CONTAINS(firstname, 'ROY')
).room_join.CALCULATE(
    room_name=roomname
)

dept_total_credits = departments.WHERE(
    HAS(courses.classes) == 1
).CALCULATE(
    dept_code=dept_code,
    total_credits=SUM(courses.classes.course.crs_credit)
)

# Find the Volvo car with least acceleration and get its cylinder count
volvo_least_accelerate = cars_datas.WHERE(
    LOWER(car_name.make) == "volvo"
).TOP_K(1, by=accelerate.ASC()).CALCULATE(
    cylinders=cylinders
)

# Find each manufacturer's most expensive product
most_expensive_products = manufacturer.WHERE(
