).product.WHERE(
    RANKING(by=price.DESC(), per="manufacturer") == 1
).CALCULATE(
    manufacturer_name=manufacturer_join.name,
    product_name=name,
    price=price
)

usa_car_models_count = car_1.CALCULATE(
