# Count drivers from Hartford city or younger than 40
driver_count = school_bus.CALCULATE(
    count_drivers = COUNT(drivers.WHERE(
        (home_city == "Hartford") | (age < 40)
    ))
)

num_people_reviewed = yelp.businesses.WHERE(
