)

# Find products that are never booked with amount higher than 200
products_never_high_amount = products_for_hires.WHERE(
    HAS(products_bookeds) == 1
).WHERE(
    MAX(products_bookeds.booked_amount) <= 200
)

# Count these products
result = products_for_hire.CALCULATE(
    count_products=COUNT(products_never_high_amount)
)

storm_region_counts = storms.CALCULATE(
