compatible_browsers = browsers.WHERE(
    (HAS(accelerator_compatible_browsers.WHERE(web_client_accelerator.name == 'CACHEbox'))) &
    (HAS(accelerator_compatible_browsers.WHERE(web_client_accelerator.name == 'Fasterfox')))
).CALCULATE(
    browser_name=name
)

# Get the secretary of Treasury department
treasury_secretary = managements.WHERE(
    department.name == 'Treasury'
).head.CALCULATE(
    treasury_birth_state = born_state
)

# Get the secretary of Homeland Security department  
homeland_secretary = managements.WHERE(
    department.name == 'Homeland Security'
).head.CALCULATE(
    homeland_birth_state = born_state
)

# Find states where both secretaries were born
# We need to find the intersection of birth states
result = department_management.CALCULATE(
    treasury_state = treasury_secretary.SINGULAR().treasury_birth_state,
    homeland_state = homeland_secretary.SINGULAR().homeland_birth_state
).WHERE(
    treasury_state == homeland_state
).CALCULATE(
    state = treasury_state
)

