donors_to_both_schools = school_finance.endowments.PARTITION(name="donors", by=donator_name).CALCULATE(
    donator_name=donator_name,
    has_glenn_donation=HAS(endowments.WHERE(school.school_name == "Glenn")),
    has_triton_donation=HAS(endowments.WHERE(school.school_name == "Triton"))
).WHERE(
    (has_glenn_donation == 1) & (has_triton_donation == 1)
).CALCULATE(
