)

result = real_estate_properties.property.CALCULATE(
    property_type_description=ref_property_type.property_type_description
)

# Find dates of transactions with at least 100 share count or amount bigger than 100
filtered_transactions = transaction.WHERE(
    (share_count >= 100) | (amount_of_transaction > 100)
).CALCULATE(
    date_of_transaction=date_of_transaction
)

