    hand == 'L'
).ORDER_BY(
    birth_date.ASC()
).CALCULATE(
    first_name=first_name,
    last_name=last_name
)

medicine_with_multiple_interactions = medicine_enzyme_interactions.CALCULATE(
    med_id=medicine.id,
    med_name=medicine.name
).PARTITION(
    name="medicine_groups",
    by=(med_id, med_name)
).CALCULATE(
