)

# Find station IDs in San Francisco with average bike availability above 10
san_francisco_station_ids = statuses.WHERE(
    station.city == "San Francisco"
).PARTITION(
    name="station_groups", 
    by=station_id
).WHERE(
    AVG(statuses.bikes_available) > 10
).CALCULATE(
    station_id=station_id
)

