    (HAS(ratings) == 1) & 
    (HASNOT(ratings.WHERE(reviewer.name == "Brittany Harris")) == 1)
).CALCULATE(
    movie_id=mid
)

# Find unique student IDs who attended statistics courses, ordered by attendance date
statistics_attendees = student_course_attendances.WHERE(
