    customer.credit_score < 100
).CALCULATE(
    bank_name=bank.bname
).PARTITION(name="unique_banks", by=bank_name).CALCULATE(
    bank_name=bank_name
)

# First, find the maximum number of faculties in Orange county in 2002
orange_county_max = csu_1.CALCULATE(
    max_orange_faculty = MAX(
        campuse.WHERE(county == "Orange").faculties.WHERE(year == 2002).faculty
    )
)

# Find campuses with more faculties in 2002 than the Orange county maximum
result = orange_county_max.campuse.WHERE(
    HAS(faculties.WHERE(year == 2002)) == 1
).CALCULATE(
    campus_name = campus,
    faculty_count_2002 = SUM(faculties.WHERE(year == 2002).faculty)
).WHERE(
    faculty_count_2002 > max_orange_faculty
).CALCULATE(campus_name)

# Find teachers who teach math courses
math_teachers = courses.WHERE(
    CONTAINS(LOWER(course), "math")
).course_arranges.teacher.CALCULATE(
