)

# Find countries where English is not the official language and calculate average life expectancy
countries_without_official_english = countries.WHERE(
    HASNOT(countrylanguages.WHERE((language == "English") & (isofficial == "T"))) == 1
).WHERE(
    lifeexpectancy != ""  # Filter out countries with missing life expectancy data
)

# Calculate the average life expectancy
result = world_1.CALCULATE(
    avg_life_expectancy = AVG(countries_without_official_english.lifeexpectancy)
)

avg_points_aib_club = clubs.WHERE(
