# Find the payment method of the customer with the least total quantity purchased
customer_with_least_quantity = customer.WHERE(
    HAS(customer_order.order_item) == 1
).CALCULATE(
    payment_method=payment_method,
    total_quantity=SUM(customer_order.order_item.order_quantity)
).TOP_K(1, by=total_quantity.ASC()).CALCULATE(
    payment_method=payment_method
)

# Find apartments with bookings having both "Provisional" and "Confirmed" status codes
apartments_with_both_statuses = apartment_booking.WHERE(
